payload.file_before:
$('tituloForm').textContent =
  jaConfirmado ? 'Sua presença já está confirmada'
  : naFila     ? 'Você está na lista de espera'
  : espera     ? 'Entre na lista de espera'
  :              'Confirme sua presença';

$('dicaTel').hidden = !travado;
if(travado){
  $('dicaTel').textContent = jaConfirmado
    ? 'Este número já confirmou presença. Para alterar ou cancelar, solicite à organização.'
    : 'Este número já está na fila, na ' + naEspera.posicao + 'ª posição.';
}

payload.file_after:
$('tituloForm').textContent =
  jaConfirmado ? 'Sua presença já está confirmada'
  : esperando  ? 'Você está na lista de espera'
  : naFila     ? 'Abriu lugar — confirme sua presença'
  : espera     ? 'Entre na lista de espera'
  :              'Confirme sua presença';

$('dicaTel').hidden = !jaConfirmado && !naFila;
if(jaConfirmado){
  $('dicaTel').textContent = 'Este número já confirmou presença. Para alterar ou cancelar, solicite à organização.';
} else if(esperando){
  $('dicaTel').textContent = 'Este número já está na fila, na ' + naEspera.posicao + 'ª posição.';
} else if(naFila){
  $('dicaTel').textContent = 'Você é o ' + naEspera.posicao + 'º da fila e abriu lugar: confirme agora para garantir.';
}
